    const req = http.get({ host: 'localhost', port, path: p, timeout: timeoutMs }, (res) => {
      const chunks = [];
      res.on('data', (c) => chunks.push(c));
      res.on('end', () => resolve({ status: res.statusCode, body: Buffer.concat(chunks).toString() }));
    });
    req.on('timeout', () => req.destroy(new Error('http timeout')));
    req.on('error', reject);
  });
}
const wait = (ms) => new Promise((r) => setTimeout(r, ms));

(async () => {
  console.log('STEP: spawn');
  const child = spawn('node', ['/tmp/story_78654b96a976/dist/cli.js', 'serve', '--content', 'content', '--output', 'dist', '--templates', 'templates', '--port', '3998'], { stdio: ['ignore', 'pipe', 'pipe'] });
  let out = '';
  child.stdout.on('data', (d) => (out += d));
  child.stderr.on('data', (d) => (out += d));
  child.on('exit', (c) => console.log('CHILD EXIT', c));

  await wait(1200);
  console.log('STEP: fetch /');
  const index = await get(3998, '/');
  console.log('index status:', index.status, '| ws injected:', index.body.includes('new WebSocket') && index.body.includes('__ssg_reload'));

  const page = await get(3998, '/hello.html');
  console.log('page has h1 Hello:', page.body.includes('<h1>Hello</h1>'));

  console.log('STEP: connect ws');
  const ws = new WebSocket('ws://localhost:3998/__ssg_reload');
  await new Promise((r, j) => { ws.on('open', r); ws.on('error', j); });
  const msgPromise = new Promise((r) => ws.on('message', (m) => r(String(m))));

  console.log('STEP: touch file');
  fs.writeFileSync('content/hello.md', '---\ntitle: Hello Serve\ndate: 2024-01-01\n---\n# Hello\n\nChanged live.\n');

  const msg = await Promise.race([msgPromise, wait(5000).then(() => 'TIMEOUT')]);
  console.log('ws reload message:', msg);

  await wait(300);
  const page2 = await get(3998, '/hello.html');
  console.log('rebuilt page has new content:', page2.body.includes('Changed live.'));

  ws.close();
  child.kill('SIGTERM');
  await wait(200);
  console.log('CLI output:', JSON.stringify(out.trim()));
  process.exit(0);
})().catch((e) => { console.error('E2E ERROR:', e.message); process.exit(1); });
EOF
